//! Port of `src/config/formatter.zig`.
//!
//! STATUS: ported
//!
//! Zig's `formatEntry(T, name, value, writer)` switches over `@typeInfo(T)`.
//! In Rust each formattable type implements [`FormatEntry`]:
//!
//! * `bool`, integers: `name = {value}`
//! * floats: `name = {value}` in plain decimal notation (Zig `{d}`)
//! * enums: `name = {tag name}` (generated by
//!   [`cli_enum!`](crate::cli::args::cli_enum))
//! * `()` (Zig `void`): `name = `
//! * `Option<T>`: the inner value, or `name = ` when `None`
//! * `str`/`String`/[`StringZ`]: `name = {value}`
//! * packed structs ([`cli_flags!`](crate::cli::args::cli_flags)):
//!   `name = a,no-b`
//! * all other structs and unions implement [`FormatEntry`] by hand
//!   (Zig's `formatEntry` decl), usually by calling back into
//!   [`EntryFormatter::format_entry`] for each primitive value.

use std::fmt;

use crate::cli::args::{PackedStruct, StringZ};

/// Errors that can occur while formatting an entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    WriteFailed,
    OutOfMemory,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::WriteFailed => f.write_str("error.WriteFailed"),
            Error::OutOfMemory => f.write_str("error.OutOfMemory"),
        }
    }
}

impl std::error::Error for Error {}

impl From<fmt::Error> for Error {
    fn from(_: fmt::Error) -> Self {
        Error::WriteFailed
    }
}

/// Returns a single entry formatter for the given field name and writer.
pub fn entry_formatter<'a>(name: &'a str, writer: &'a mut dyn fmt::Write) -> EntryFormatter<'a> {
    EntryFormatter { name, writer }
}

/// The entry formatter type for a given writer.
pub struct EntryFormatter<'a> {
    pub name: &'a str,
    pub writer: &'a mut dyn fmt::Write,
}

impl EntryFormatter<'_> {
    /// Format a value under this formatter's name (Zig
    /// `formatter.formatEntry(T, value)`).
    pub fn format_entry<T: FormatEntry + ?Sized>(&mut self, value: &T) -> Result<(), Error> {
        format_entry(self.name, value, &mut *self.writer)
    }
}

/// A type that can be formatted as a config entry (Zig: the built-in
/// cases of `formatEntry` plus every type's `formatEntry` decl).
pub trait FormatEntry {
    fn format_entry(&self, formatter: &mut EntryFormatter<'_>) -> Result<(), Error>;
}

/// Format a single type with the given name and value.
pub fn format_entry<T: FormatEntry + ?Sized>(
    name: &str,
    value: &T,
    writer: &mut dyn fmt::Write,
) -> Result<(), Error> {
    value.format_entry(&mut EntryFormatter { name, writer })
}

/// Formats an enum value by its tag name. Used by
/// [`cli_enum!`](crate::cli::args::cli_enum).
pub fn format_enum(formatter: &mut EntryFormatter<'_>, tag: &str) -> Result<(), Error> {
    write!(formatter.writer, "{} = {}\n", formatter.name, tag)?;
    Ok(())
}

/// Formats a packed struct as `a,no-b,...`. Used by
/// [`cli_flags!`](crate::cli::args::cli_flags).
pub fn format_packed_struct<T: PackedStruct>(
    value: &T,
    formatter: &mut EntryFormatter<'_>,
) -> Result<(), Error> {
    write!(formatter.writer, "{} = ", formatter.name)?;
    for (i, field) in T::FIELD_NAMES.iter().enumerate() {
        if i > 0 {
            write!(formatter.writer, ",")?;
        }
        write!(
            formatter.writer,
            "{}{}",
            if !value.get_field(i) { "no-" } else { "" },
            field
        )?;
    }
    write!(formatter.writer, "\n")?;
    Ok(())
}

impl FormatEntry for bool {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        write!(f.writer, "{} = {}\n", f.name, self)?;
        Ok(())
    }
}

macro_rules! impl_format_int {
    ($($t:ty),*) => {$(
        impl FormatEntry for $t {
            fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
                write!(f.writer, "{} = {}\n", f.name, self)?;
                Ok(())
            }
        }
    )*};
}
impl_format_int!(u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);

macro_rules! impl_format_float {
    ($($t:ty),*) => {$(
        impl FormatEntry for $t {
            fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
                // Zig's `{d}` prints plain decimal notation like Rust's
                // `Display`, but spells NaN as "nan".
                if self.is_nan() {
                    write!(f.writer, "{} = nan\n", f.name)?;
                } else {
                    write!(f.writer, "{} = {}\n", f.name, self)?;
                }
                Ok(())
            }
        }
    )*};
}
impl_format_float!(f32, f64);

impl FormatEntry for () {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        write!(f.writer, "{} = \n", f.name)?;
        Ok(())
    }
}

impl<T: FormatEntry> FormatEntry for Option<T> {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        match self {
            Some(inner) => inner.format_entry(f),
            None => {
                write!(f.writer, "{} = \n", f.name)?;
                Ok(())
            }
        }
    }
}

impl FormatEntry for str {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        write!(f.writer, "{} = {}\n", f.name, self)?;
        Ok(())
    }
}

impl FormatEntry for String {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        self.as_str().format_entry(f)
    }
}

impl FormatEntry for StringZ {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        self.as_str().format_entry(f)
    }
}

impl<T: FormatEntry + ?Sized> FormatEntry for &T {
    fn format_entry(&self, f: &mut EntryFormatter<'_>) -> Result<(), Error> {
        (**self).format_entry(f)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::cli::args::{cli_enum, cli_flags};

    #[test]
    fn format_entry_bool() {
        {
            let mut buf = String::new();
            format_entry("a", &true, &mut buf).unwrap();
            assert_eq!("a = true\n", buf);
        }

        {
            let mut buf = String::new();
            format_entry("a", &false, &mut buf).unwrap();
            assert_eq!("a = false\n", buf);
        }
    }

    #[test]
    fn format_entry_int() {
        let mut buf = String::new();
        format_entry("a", &123u8, &mut buf).unwrap();
        assert_eq!("a = 123\n", buf);
    }

    #[test]
    fn format_entry_float() {
        let mut buf = String::new();
        format_entry("a", &0.7f64, &mut buf).unwrap();
        assert_eq!("a = 0.7\n", buf);
    }

    #[test]
    fn format_entry_enum() {
        cli_enum! {
            enum Enum { One => "one", Two => "two", Three => "three" }
        }
        let _ = (Enum::One, Enum::Three);

        let mut buf = String::new();
        format_entry("a", &Enum::Two, &mut buf).unwrap();
        assert_eq!("a = two\n", buf);
    }

    #[test]
    fn format_entry_void() {
        let mut buf = String::new();
        format_entry("a", &(), &mut buf).unwrap();
        assert_eq!("a = \n", buf);
    }

    #[test]
    fn format_entry_optional() {
        {
            let mut buf = String::new();
            format_entry("a", &None::<bool>, &mut buf).unwrap();
            assert_eq!("a = \n", buf);
        }

        {
            let mut buf = String::new();
            format_entry("a", &Some(false), &mut buf).unwrap();
            assert_eq!("a = false\n", buf);
        }
    }

    #[test]
    fn format_entry_string() {
        let mut buf = String::new();
        format_entry("a", "hello", &mut buf).unwrap();
        assert_eq!("a = hello\n", buf);
    }

    #[test]
    fn format_entry_packed_struct() {
        cli_flags! {
            struct Value {
                one: bool = true,
                two: bool = false,
            }
        }

        let mut buf = String::new();
        format_entry("a", &Value::default(), &mut buf).unwrap();
        assert_eq!("a = one,no-two\n", buf);
    }
}
